func is_transaction_open() -> bool:
	"""True while an explicit transaction is accepting operations."""
	return _tx_open

func total_equipped_milli(item_id: int) -> int:
	"""Quantity of an item currently held as equipment, charged to no container at all.

	DIAGNOSTIC, like total_live_milli(): a bounded walk of the lot column, not a tick query.
	"""
	var total: int = 0
	for slot: int in range(_l_slot_high_water):
		if _l_live[slot] != 1 or _l_item_id[slot] != item_id:
			continue
		if _l_container_slot[slot] == NULL_SLOT:
			total += _l_quantity_milli[slot]
	return total

func container_first_lot(container_ref: Vector2i) -> Vector2i:
	"""Head of a container's lot list, for deterministic iteration with container_next_lot()."""
	if not is_container_valid(container_ref):
		return NULL_REF
	return _lot_ref_of(_c_first_lot[container_ref.x])

func container_next_lot(lot_ref: Vector2i) -> Vector2i:
	"""Next lot after `lot_ref` in its container's list, or the null ref at the end."""
	if not is_lot_valid(lot_ref):
		return NULL_REF
	return _lot_ref_of(_l_next[lot_ref.x])

func lot_quantity_milli(lot_ref: Vector2i) -> int:
	"""Total quantity on a lot in milli-units, or 0 for an invalid ref."""
	return _l_quantity_milli[lot_ref.x] if is_lot_valid(lot_ref) else 0

func lot_reserved_milli(lot_ref: Vector2i) -> int:
	"""Claimed quantity on a lot in milli-units, or 0 for an invalid ref."""
	return _l_reserved_milli[lot_ref.x] if is_lot_valid(lot_ref) else 0

func lot_available_milli(lot_ref: Vector2i) -> int:
	"""Unclaimed quantity on a lot: quantity_milli - reserved_milli."""
	if not is_lot_valid(lot_ref):
		return 0
	return _l_quantity_milli[lot_ref.x] - _l_reserved_milli[lot_ref.x]

func lot_age_milli_hours(lot_ref: Vector2i) -> int:
	"""Effective storage age of a lot in milli-hours, or -1 for an invalid ref."""
	return _l_age_milli_hours[lot_ref.x] if is_lot_valid(lot_ref) else -1

func container_reachable(container_ref: Vector2i) -> bool:
	"""True when a container is currently reachable for hauling."""
	return _c_reachable[container_ref.x] == 1 if is_container_valid(container_ref) else false

func canonical_capacities() -> Vector2i:
	"""This store's `(container_capacity, lot_capacity)`, so a caller can size a buffer."""
	return Vector2i(_c_capacity, _l_capacity)

func create_generated_settlement(items: ItemDefinitionsScript,
		world_seed: int = WorldInitScript.TUTORIAL_WORLD_SEED) -> bool:
	"""REQ-SET-009 end to end: §5.1's cohort takes ids 1-12, then §5.1's world follows from 13.

	THE GAP THIS CLOSES. `world_init.gd` built the world and `create_initial_settlement()` built
	the population, and NOTHING CALLED BOTH -- so generating produced an empty world and booting
	produced a cohort with nowhere to stand. §5.1 states one initialization contract, not two, and
	this is the single operation that satisfies it.

	THE ORDER IS THE RULING'S (R-INIT-ID-001, decision 0075), AND IT IS THE REVERSE OF DECISION
	0071's. That decision recorded that `world_init._publish()` cleared the directory, forcing the
	world to be created first and leaving the cohort on ids 1714-1725 instead of §5.1's "IDs 1-12".
	The specification owner ruled that the clear is a reset BEFORE new-world allocation, not a
	second reset inside terrain publication. So this operation is now one transaction:

	  1. PREFLIGHT, changing nothing: the settlement must be empty, the seventeen resource ids must
	     bind, the world plan must stage and validate, and the cohort's own catalog, capacities and
	     opening-day weather must check out. Every refusal below is decided here.
	  2. ENTER THE TRANSACTION: `reset()` once -- stores, directory, allocators, command, job and
	     child state -- then seed the nine RNG streams, before any consumer draws.
	  3. ALLOCATE THE TWELVE RESIDENTS FIRST, in §5.1's cohort order, through the ordinary
	     directory allocator. They receive persistent ids 1-12 and Warden Rowan receives 1.
	  4. PUBLISH THE WORLD from the SAME continuing counter, so the first world entity is 13.
	     `publish_prepared()` clears and reseeds nothing.

	ALLOCATE BEFORE CONSUME (decision 0059). A populated settlement refuses at step 1 and is
	byte-identical afterwards, which is how "a refused initialization retains the previous valid
	world" is honoured: the only world this can overwrite is one with nobody in it. See
	`_abandon_transaction()` for what an in-transaction failure can and cannot restore.
	"""
	if _residents.population() != 0:
		return _refuse(ResidentsScript.REFUSE_SETTLEMENT_NOT_EMPTY)
	if _world.is_published():
		return _refuse(REFUSE_WORLD_ALREADY_PUBLISHED)
	var built: WorldInitScript.RequestResult = WorldInitScript.bound_request(items, world_seed)
	if not built.ok:
		return _refuse(built.error)
	var planned: WorldInitScript.GenerateResult = _world.preflight(built.request)
	if not planned.ok:
		return _refuse(planned.error)
	var cohort: StringName = _refuse_cohort_preflight()
	if cohort != REFUSE_NONE:
		_world.discard_prepared_plan()
		return _refuse(cohort)
	return _run_initialization_transaction()

func inventory() -> InventoryScript:
	"""The settlement's own InventoryLot/InventoryContainer store, the one ARCH-SYS-004 ages."""
	return _inventory

func item_definitions() -> ItemDefinitionsScript:
	"""The §4.3 item catalog registered into this settlement's inventory."""
	return _item_definitions

func residents() -> ResidentsScript:
	"""The settlement's population. EconomySystem BORROWS this as its food-days divisor."""
	return _residents

func _on_stocks_changed() -> void:
	"""Repaint the top-left counters after a committed change to the stores."""
	_refresh_counters()

func is_loaded() -> bool:
	"""True once load_from_file()/load_default() has fully succeeded on this instance."""
	return _loaded

func item_count() -> int:
	"""Number of items loaded, or 0 before a successful load."""
	return _item_count

func compiled_id(item_id: StringName) -> int:
	"""Compiled ItemDefinition id for `item_id`, or -1 if unknown or not yet loaded."""
	if not _item_ids.has(item_id):
		return -1
	return _item_ids[item_id]

func nutrition_per_u(compiled_item_id: int) -> int:
	"""Nutrition per catalog unit for a compiled item id, or 0 if out of range."""
	if compiled_item_id < 0 or compiled_item_id >= _item_count:
		return 0
	return _nutrition_per_u[compiled_item_id]

func shelf_hours(compiled_item_id: int) -> int:
	"""Shelf life in hours for a compiled item id (0 means unlimited), or 0 if out of range."""
	if compiled_item_id < 0 or compiled_item_id >= _item_count:
		return 0
	return _shelf_hours[compiled_item_id]

func is_raw_edible(compiled_item_id: int) -> bool:
	"""True when a compiled item id is directly edible without a recipe."""
	if compiled_item_id < 0 or compiled_item_id >= _item_count:
		return false
	return _raw_edible[compiled_item_id] == 1

func is_seed(compiled_item_id: int) -> bool:
	"""True when a compiled item id is plantable seed stock."""
	if compiled_item_id < 0 or compiled_item_id >= _item_count:
		return false
	return _seed[compiled_item_id] == 1
